		{"case_variant", "entries", []string{"Grape"}, 422},
		{"whitespace", "entries", []string{" grape"}, 422},
		{"too_many", "entries", []string{"young", "grape", "weekend", "danger", "enforce", "learn"}, 422},
		{"prompt", "prompt", "synthetic unwanted prompt", 400},
